    def components():
        pts=[(r,c) for r in range(H) for c in range(W) if g[r][c]==5]; seen=set(); res=[]
        for p in pts:
            if p in seen: continue
            stack=[p]; comp={p}; seen.add(p)
            while stack:
                r_,c_=stack.pop()
                for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                    q=(r_+dr,c_+dc)
                    if q not in seen and 0<=q[0]<H and 0<=q[1]<W and g[q[0]][q[1]]==5:
                        seen.add(q); comp.add(q); stack.append(q)
            rs=[x[0] for x in comp]; cs=[x[1] for x in comp]
            R0,R1,C0,C1=min(rs),max(rs),min(cs),max(cs)
            if R0<R1 and C0<C1: res.append((R0,C0,R1,C1))
        return res
    for R0,C0,R1,C1 in sorted(components(), key=lambda t:(t[1]-t[0])*(t[3]-t[2]), reverse=True):
        h=R1-R0+1; w=C1-C0+1
        if h!=w: continue
        for k in range(1,(h-1)//2+1):
            side=h-2*k
            if side<=1 or side%3==0: continue
            col=2 if k%2==1 else 5
            for rr in range(R0+k,R1-k+1):
                o[rr][C0+k]=col; o[rr][C1-k]=col
            for cc in range(C0+k,C1-k+1):
                o[R0+k][cc]=col; o[R1-k][cc]=col
    return o
